type answerDoneMsg struct {
	index int // the step the question was asked at
	steps []tour.Step
	stats generate.Stats
	err   error
}

// in updateAsk, case answerDoneMsg:
v.ctx.Tour.InsertAfter(msg.index, msg.steps)
v.steps = v.ctx.Tour.Steps()
if v.index > msg.index {
	v.index += len(msg.steps) // stay on the step being read
}
